skills.content:
if event.trigger_name == "on_turn_start" && player.get_current_block().has_skill("shelter"):
	player.add_mark_skill("shelter_disabled", 1, "turn_end", "避难所", "本回合内无触发避难所的庇护", true)
elif event.trigger_name == "on_take_damage" && player.get_current_block().has_skill("shelter"):
	event["cancel"].call()

if event.trigger_name == "on_reveal_block":
	var food_cards = []
	for c in player.get_cards():
		if c.english_name.begins_with("food_"):
			food_cards.append(c)
	player.discard(food_cards)
elif event.trigger_name == "on_enter_block" && player.get_current_block().has_skill("power_plant"):
	player.add_poison(1)

var block = player.get_current_block()
if block != null and not block.is_revealed():
	await block.reveal(true, player)
if not await player.sneak_judge():
	await player.move_to(event["source_block"])

var candidates = []
for b in game.map_area:
	if b.is_revealed() and not b.has_monster_mark() and b != player.get_current_block():
		candidates.append(b)
if candidates.is_empty():
	EventSystem.cancel(event)
	return
var chosen = await player.choose_block_inline(candidates, "\"机场\": 选择目标地图块", 1)
if chosen.is_empty():
	EventSystem.cancel(event)
	return
target = chosen[0]
player.consume_action(1)
await player.move_to(target)

var list = game.get_engaged_monsters(player)
for i in list:
	await i.damage(2, player)

if event.trigger_name == "on_reveal_block" && player.in_phase == "action":
	player.end_phase("action")
elif event.trigger_name == "on_enter_block" && player.get_current_block().has_skill("prison"):
	player.consume_action(1)

var list = player.get_current_block().get_adjacent_blocks()
for i in list:
	i.add_monster_mark(1)

skills.filter:
if player.in_phase != "action" or player.get_number("action_count") <= 0:
	return false
var block = player.get_current_block()
if block == null or not block.has_skill("van"):
	return false
if game.mission_config == null or game.mission_config.van_fuel_required <= 0:
	return false
if block.get_van_fuel() < block.get_van_fuel_max():
	return player.get_equipment("fuel") != null
if block.has_monster() or block.has_monster_mark():
	return false
for p in game.get_all_players():
	if p.is_alive() and p.get_current_block() != block:
		return false
return true

skills.confirm_prompt:
var block = player.get_current_block()
if block.get_van_fuel() < block.get_van_fuel_max():
	return '行动：是否给 "面包车" 添加一桶燃料'
else:
	return '行动：是否启动 "面包车" 离开'

skills.content:
player.consume_action(1)
var block = player.get_current_block()
if block.get_van_fuel() < block.get_van_fuel_max():
	block.add_van_fuel(1)
	var fuel_equip = player.get_equipment("fuel")
	if fuel_equip != null:
		await player.discard(fuel_equip)
else:
	game.game_over("win")

if event.trigger_name == "on_reveal_block":
	var list = game.get_all_players()
	for i in list:
		i.draw_monster(1)
elif event.trigger_name == "on_enter_block":
	player.draw_monster(1)

var equip_cards = []
for c in player.get_cards():
	if c.card_type == "equipment":
		equip_cards.append(c)
if equip_cards.is_empty():
	player.damage(5, null)
elif await player.confirm("\"强盗营地\": 是否弃置一张装备牌，否则受到 5 点伤害"):
	var chosen = await player.choose_card(1, equip_cards)
	if chosen.is_empty():
		player.damage(5, null)
	else:
		player.discard(chosen)
else:
	player.damage(5, null)

var candidates = []
for b in game.map_area:
	if b.has_skill("tunnel") and b != player.get_current_block():
		candidates.append(b)
if candidates.is_empty():
	EventSystem.cancel(event)
	return
var chosen = await player.choose_block_inline(candidates, "\"隧道\": 选择目标地图块", 1)
if chosen.is_empty():
	EventSystem.cancel(event)
	return
target = chosen[0]
player.consume_action(1)
await player.move_to(target)

if event.trigger_name == "on_enter_block":
	player.add_mark_skill("forest_monster", 1, "turn_end", "森林", "本回合内移动出森林抓取一张怪物牌", false)
elif event.trigger_name == "on_leave_block" && player.has_mark_skill("forest_monster"):
	player.draw_monster(1)

if event.trigger_name == "on_reveal_block":
	player.choose_to_discard(3)
elif event.trigger_name == "on_turn_end":
	player.choose_to_discard(1)

if event.trigger_name == "on_enter_block":
	player.recover(1)
elif event.trigger_name == "on_turn_end":
	player.recover(2)

if event.trigger_name == "on_reveal_block":
	var list = game.get_all_players()
	for i in list:
		if i.has_card("equipment"):
			var card = game.get_random_card(i, ["equipment"])
			if card != null:
				i.remove_card(card)
elif event.trigger_name == "on_enter_block" && player.has_card():
	var card = game.get_random_card(player, ["hand", "equipment"])
	if card != null:
		player.remove_card(card)
